async function execute() {
  const srcPath = "mnemopay-sdk/src/governance/audit-chain.ts";
  const testPath = "mnemopay-sdk/tests/audit-chain.test.ts";

  const src = await tools.readFile({ path: srcPath });
  const test = await tools.readFile({ path: testPath });
  if (src.truncated || test.truncated) {
    return { __starclaw: "continue", observation: { error: "file truncated", srcTrunc: src.truncated, testTrunc: test.truncated } };
  }

  const srcEol = src.content.includes("\r\n") ? "\r\n" : "\n";
  const testEol = test.content.includes("\r\n") ? "\r\n" : "\n";
  const fix = (s, eol) => s.replace(/\n/g, eol);

  // ---- source edit ----
  let newSrc = src.content;
  const unionFind = '{ ok: false; reason: "root_mismatch" | "bad_event_signature"; index?: number }';
  const unionRepl = '{ ok: false; reason: "root_mismatch" | "bad_event_signature" | "sequence_mismatch"; index?: number }';
  const rootFind = '  if (layer[0] !== bundle.merkle_root) return { ok: false, reason: "root_mismatch" };';
  const rootRepl = rootFind + fix(`

  // The Merkle tree pads an odd layer by repeating the last leaf, so a bundle
  // whose last event was duplicated can hash to the same root. AuditChain
  // assigns consecutive sequence numbers, so require them here. The root
  // computation is unchanged.
  const firstSeq = bundle.events[0]!.sequence;
  for (let i = 0; i < bundle.events.length; i++) {
    const seq = bundle.events[i]!.sequence;
    if (typeof seq !== "number" || seq !== firstSeq + i) {
      return { ok: false, reason: "sequence_mismatch", index: i };
    }
  }`, srcEol);

  if (newSrc.split(unionFind).length !== 2 || newSrc.split(rootFind).length !== 2) {
    return {
      __starclaw: "continue",
      observation: {
        error: "anchor not found exactly once in source",
        unionFound: newSrc.split(unionFind).length - 1,
        rootFound: newSrc.split(rootFind).length - 1,
        srcHead: newSrc.slice(0, 6000),
        testHead: test.content.slice(0, 3000)
      }
    };
  }
  newSrc = newSrc.replace(unionFind, () => unionRepl).replace(rootFind, () => rootRepl);

  // ---- test edit ----
  const addition = fix(`
describe("verifyBundle duplicated-last-event tampering", () => {
  function buildChain(count: number, sequence_start?: number) {
    const chain = new AuditChain(sequence_start === undefined ? {} : { sequence_start });
    for (let i = 0; i < count; i++) chain.emit("test.event", { i });
    return chain;
  }

  it("rejects a bundle whose last event was duplicated (odd count)", () => {
    const bundle = buildChain(3).toBundle();
    expect(verifyBundle(bundle).ok).toBe(true);

    const tampered = {
      ...bundle,
      events: [...bundle.events, bundle.events[bundle.events.length - 1]!],
    };
    // Same root: this is exactly why the Merkle check alone cannot catch it.
    expect(tampered.merkle_root).toBe(bundle.merkle_root);
    const result = verifyBundle(tampered);
    expect(result.ok).toBe(false);
    if (!result.ok) expect(result.reason).toBe("sequence_mismatch");
  });

  it("still verifies untampered bundles (odd, even, single, custom start)", () => {
    for (const n of [1, 2, 3, 4, 5, 7]) {
      expect(verifyBundle(buildChain(n).toBundle()).ok).toBe(true);
    }
    expect(verifyBundle(buildChain(3, 100).toBundle()).ok).toBe(true);
  });
});
`, testEol);
  const newTest = test.content.replace(/\s*$/, "") + testEol + addition;

  await tools.writeFile({ path: srcPath, content: newSrc });
  await tools.writeFile({ path: testPath, content: newTest });

  // ---- verify by reading back ----
  const s2 = await tools.readFile({ path: srcPath });
  const t2 = await tools.readFile({ path: testPath });
  const obs = {
    srcHasFix: s2.content.includes("sequence_mismatch") && s2.content.includes("firstSeq"),
    testHasNew: t2.content.includes("duplicated-last-event tampering"),
    importsLine: t2.content.split(/\r?\n/).filter(l => l.startsWith("import")).slice(0, 6),
  };

  try {
    const r = await tools.shell({ command: "cd /work/mnemopay-sdk && ls node_modules >/dev/null 2>&1 && npx --no-install vitest run tests/audit-chain.test.ts 2>&1 | tail -30 || echo 'no node_modules; tests not run'" });
    obs.testRun = { exitCode: r.exitCode, out: (r.stdout || "").slice(-1500) };
  } catch (e) {
    obs.testRun = "shell unavailable: " + String(e).slice(0, 200);
  }
  console.log(JSON.stringify(obs));
  return { __starclaw: "continue", observation: obs };
}","escalatedByTaint":false,"origin":"owner","policySource":"default","summary":"Run generated JavaScript (sha256 6ccf6b0128bb, 4491 chars) in the isolated sandbox; its tool calls are governed individually","taintSources":["tool-output:directory:C:\Users\bizsu\Projects\starclaw-demo-run10\openrouter\workspace","tool-output:directory:C:\Users\bizsu\Projects\starclaw-demo-run10\openrouter\workspace\mnemopay-sdk","tool-output:directory:C:\Users\bizsu\Projects\starclaw-demo-run10\openrouter\workspace\workspace","tainted-file:C:\Users\bizsu\Projects\starclaw-demo-run10\openrouter\workspace\mnemopay-sdk\src\governance\audit-chain.ts","tainted-file:C:\Users\bizsu\Projects\starclaw-demo-run10\openrouter\workspace\mnemopay-sdk\tests\audit-chain.test.ts","tool-output:agent-step:1"],"tainted":true,"target":"sandbox:js","verdictBeforeApproval":"ask"},"starclaw":{"seq":36,"prev":"48a0278a98698d1d65d83b27e186f65cf383ce662aa62b080dad0bfbe21d713e","hash":"3dcf804b2aa44a57fb570ad7cef0ba8f39b00a46bdb385251ce779eb7afbf7bb","sig":"sNZK6D+rH9tSO0/76WATVi0r7xo4CbEb6h5D7vJ4ggiKeNJXr4JS1hQ/gvvy1GeuBOuJDSTua8t6F3wJbEEvBA=="}}

